head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/****************************************
 * 초기값 설정 - 사용자 지정값
 * SHIFT_VERSION           - ShiftCrossBrowser Plugin의 버전
 * SHIFT_FILE              - ShiftCrossBrowser Plugin의 다운받을 경로
 * SHIFT_OPENWINDOW        - window.open 함수 실행시 Plugin에서 생성하는 FrameSet을 사용할지 여부
 * SHIFT_OPENWINDOW_OPTION - Plugin에서 생성하는 FrameSet의 옵션 값
 **       caption     - 캡션 사용 유무 (default true)
 * SHIFT_OPENWINDOW_TITLEICON - Plugin에서 생성하는 FrameSet의 ICON을 지정
 **       http:, https:, ftp: 로 시작되는 경로만을 지원
 **       ""(공백)을 줄 경우 실행된 브라우저 ICON으로 대처
 **       ico 파일 포맷만 지원 (8bit, 256 color 권장)
 * SHIFT_BACKGROUND - 다운로드 대기 화면 이미지 경로         
 * SHIFT_CHROME_EXTENTION	 - ShiftCrossBrowser Chrome Extension 설치 경로를 기술한다.
 **			내부망 사용자 : crx 경로 지정 (처음 설치 및 업데이트 파일 설정)
 **			외부망 사용자 : 웹스토어 경로 지정 (https://chrome.google.com/webstore/detail/comshiftcrossbrowser/ebekhloadibdodgeanmhbbkeenkmllln)
 * SHIFT_LICENSE_KEY - ShiftCrossBrowser 라이선스 키
 * SHIFT_CHROME_EXE - ShiftCrossBrowser.exe 다운로드 경로를 기술한다.
 * SHIFT_BROWSER_EMULATION - 브라우저 호환성 기능을 지정한다 (defalut - 7000)
 **         11001 : !DOCTYPE 선언과 상관없이 IE11 edge로 출력
 **         11000 : standards-based !DOCTYPE 선언이 있을 경우 IE11 edge로 출력
 **         10001 : !DOCTYPE 선언과 상관없이 IE10 Standards mode로 출력
 **         10000 : standards-based !DOCTYPE 선언이 있을 경우 IE10 Standards mode로 출력
 **         9999 : !DOCTYPE 선언과 상관없이 IE9 Standards mode로 출력
 **         9000 : standards-based !DOCTYPE 선언이 있을 경우 IE9 mode로 출력
 **         8888 : !DOCTYPE 선언과 상관없이 IE8 Standards mode로 출력
 **         8000 : standards-based !DOCTYPE 선언이 있을 경우 IE8 Mode로 실행
 **         7000 : standards-based !DOCTYPE 선언이 있을 경우 IE7 Standards mode로 실행
 * SHIFT_USER_DOWNLOADPAGE - 사용자 다운로드 페이지를 지정한다.
 **			URL을 지정하는 경우 크롬웹스토어 및 ShiftCrossBrowser.exe 다운로드 페이지가 아닌 지정된 페이지로 이동시킨다.
 ****************************************/
scwin.SHIFT_VERSION = "2.2.0.21";
scwin.SHIFT_FILE = "./file/ShiftCrossBrowser.exe";
scwin.SHIFT_OPENWINDOW = "true";
scwin.SHIFT_OPENWINDOW_OPTION = "caption=1,dpi=1";
scwin.SHIFT_OPENWINDOW_TITLEICON = "";
scwin.SHIFT_BACKGROUND = "image/loading_img.gif";
//var SHIFT_CHROME_EXTENTION = "https://chrome.google.com/webstore/detail/shiftcrossbrowser/ebkefifccmcgdjmpijmfamimgoaflkmd"; //외부망 사용자 (인터넷 가능)
//var SHIFT_CHROME_EXTENTION = "http://127.0.0.1/file/ShiftCrossBrowser_v2.2.0.18.crx"; //내부망 사용자 (인터넷 불가)


scwin.SHIFT_CHROME_EXTENTION_FILE = "/activeupdate/ShiftCrossBrowser_v" + scwin.SHIFT_VERSION + ".crx";
scwin.SVR_GUBUN = "manager";
scwin.SVR_DOMAIN = "https://" + scwin.SVR_GUBUN + ".krx.co.kr";
scwin.SHIFT_CHROME_EXTENTION;
scwin.SHIFT_CHROME_EXE_FILE = "/activeupdate/ShiftCrossBrowser.exe";
scwin.SHIFT_CHROME_EXE;
scwin.svrUrl = window.location.href;
scwin.svrChk = scwin.svrUrl.substr(scwin.svrUrl.indexOf(':') + 3, 3);
if (scwin.svrChk == 'dev') {
    scwin.SVR_DOMAIN = "https://dev-" + scwin.SVR_GUBUN + ".krx.co.kr";
} else if (scwin.svrChk == 'tes') {
    scwin.SVR_DOMAIN = "https://test-" + scwin.SVR_GUBUN + ".krx.co.kr";
} else if (scwin.svrChk == 'loc') {
    scwin.SVR_DOMAIN = "http://localhost:8081";
}
scwin.SHIFT_CHROME_EXTENTION = scwin.SVR_DOMAIN + scwin.SHIFT_CHROME_EXTENTION_FILE;
scwin.SHIFT_CHROME_EXE = scwin.SVR_DOMAIN + scwin.SHIFT_CHROME_EXE_FILE;
SHIFT_LICENSE_KEY = "16sift.CBXs/Fp1fgeWEQ6u5m3ncsZw=="; //2025.10.13 (만료일 2025.11.13)
//var SHIFT_CHROME_EXE = "";	//외부망 사용자 (인터넷 가능)(http://member.shift.co.kr/download/ShiftCrossBrowser/(version)/ShiftCrossBrowser.exe)
//var SHIFT_CHROME_EXE = "http://127.0.0.1/file/ShiftCrossBrowser.exe"; //내부망 사용자 (인터넷 불가) 
scwin.SHIFT_BROWSER_EMULATION = "";
scwin.SHIFT_USER_DOWNLOADPAGE = ""; //http://127.0.0.1/Download.html

scwin.SHIFT_DEFAULT_URL = document.location;
scwin.SHIFT_DEFAULT_WIDTH = "100%";
scwin.SHIFT_DEFAULT_HEIGHT = "100%";
scwin.SHIFT_DEFAULT_PLUGINLOAD = "false";
scwin.SHIFT_DEFAULT_PLUGININSTALL = "false";
scwin.SHIFT_DEFAULT_MIME = "shift.co.kr/shift-crossbrowser-plugin";
scwin.SHIFT_DEFAULT_INTERVARCNT = 0;
scwin.SHIFT_DEFAULT_REPLACEFLAG;
scwin.SHIFT_SETINTERVAL = 60;
scwin.SHIFT_TITLE = "true";
scwin.SHIFT_STATUSTEXT = "false";
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
/**
 * @method
 * @name ShiftCrossBrowser_pluginVersion
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_pluginVersion = function() {
    var _activexName = "InnoxyncContainer.InnoxyncEmulator";
    if (window.ActiveXObject) {
        try {
            var _obj = new ActiveXObject(_activexName);
            scwin.SHIFT_DEFAULT_PLUGINLOAD = "true";
            var version = _obj.version;
            var sVersion = scwin.SHIFT_VERSION.split(".");
            var lVersion = version.split(".");
            for (var i = 0; i <= 3; i++) {
                if (Number(sVersion[i]) > Number(lVersion[i])) {
                    scwin.SHIFT_DEFAULT_PLUGININSTALL = "true";
                    break;
                }
            }
            _obj = null;
        } catch (e) {

        }
    } else {
        var plugins = navigator.plugins;
        var version = "";
        for (var i = 0; i < plugins.length; i++) {
            var type = plugins[i][0].type;
            if (type.indexOf(scwin.SHIFT_DEFAULT_MIME) != -1) {
                scwin.SHIFT_DEFAULT_PLUGINLOAD = "true";
                version = type.substr(type.indexOf("=") + 1, type.length);
                break;
            }
        }
        var sVersion = scwin.SHIFT_VERSION.split(".");
        var lVersion = version.split(".");
        if (Number(sVersion[3]) < Number(lVersion[3])) {
            scwin.SHIFT_VERSION = version;
            return;
        }
        for (var i = 0; i <= 3; i++) {
            if (Number(sVersion[i]) > Number(lVersion[i])) {
                scwin.SHIFT_DEFAULT_PLUGININSTALL = "true";
                break;
            }
        }
    }
};
/**
 * @method
 * @name ShiftCrossBrowser_pluginReplace
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_pluginReplace = function() {
    if (scwin.SHIFT_DEFAULT_INTERVARCNT > scwin.SHIFT_SETINTERVAL) clearInterval(scwin.SHIFT_DEFAULT_REPLACEFLAG);
    scwin.SHIFT_DEFAULT_INTERVARCNT++;
    var _activexName = "InnoxyncContainer.InnoxyncEmulator";
    if (window.ActiveXObject) {
        try {
            var _obj = new ActiveXObject(_activexName);
            clearInterval(scwin.SHIFT_DEFAULT_REPLACEFLAG);
            location.replace(document.location);
        } catch (e) {

        }
        return;
    } else {
        navigator.plugins.refresh();
        var plugins = navigator.plugins;
        for (var i = 0; i < plugins.length; i++) {
            var type = plugins[i][0].type;
            if (type.indexOf(scwin.SHIFT_DEFAULT_MIME) != -1 && type.indexOf(scwin.SHIFT_VERSION) != -1) {
                clearInterval(scwin.SHIFT_DEFAULT_REPLACEFLAG);
                location.replace(scwin.SHIFT_DEFAULT_URL);
                break;
            }
        }
    }
};
/**
 * @method
 * @name ShiftCrossBrowser_pluginDownload
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_pluginDownload = function() {
    document.location.href = scwin.SHIFT_FILE;
};
/**
 * @method
 * @name npShiftCrossB_title
 * @description desc
 * @param {string} title desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.npShiftCrossB_title = function(title) {
    if (scwin.SHIFT_TITLE = "true") document.title = scwin.ShiftCrossBrowser_base64.decode(title);
};
/**
 * @method
 * @name npShiftCrossB_status
 * @description desc
 * @param {string} text desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.npShiftCrossB_status = function(text) {
    if (scwin.SHIFT_STATUSTEXT = "true") window.status = scwin.ShiftCrossBrowser_base64.decode(text);
};
scwin.ShiftCrossBrowser_base64 = {
    _keyStr: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=",
    decode__function: function(input) {
        var output = "";
        var chr1, chr2, chr3;
        var enc1, enc2, enc3, enc4;
        var i = 0;
        input = input.replace(/[^A-Za-z0-9\+\/\=]/g, "");
        while (i < input.length) {
            enc1 = this._keyStr.indexOf(input.charAt(i++));
            enc2 = this._keyStr.indexOf(input.charAt(i++));
            enc3 = this._keyStr.indexOf(input.charAt(i++));
            enc4 = this._keyStr.indexOf(input.charAt(i++));
            chr1 = (enc1 << 2) | (enc2 >> 4);
            chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
            chr3 = ((enc3 & 3) << 6) | enc4;
            output = output + String.fromCharCode(chr1);
            if (enc3 != 64) {
                output = output + String.fromCharCode(chr2);
            }
            if (enc4 != 64) {
                output = output + String.fromCharCode(chr3);
            }
        }
        output = scwin.ShiftCrossBrowser_base64._utf8_decode(output);
        return output;
    },
    _utf8_decode__function: function(utftext) {
        var string = "";
        var i = 0;
        var c = c1 = c2 = 0;
        while (i < utftext.length) {
            c = utftext.charCodeAt(i);
            if (c < 128) {
                string += String.fromCharCode(c);
                i++;
            } else if ((c > 191) && (c < 224)) {
                c2 = utftext.charCodeAt(i + 1);
                string += String.fromCharCode(((c & 31) << 6) | (c2 & 63));
                i += 2;
            } else {
                c2 = utftext.charCodeAt(i + 1);
                c3 = utftext.charCodeAt(i + 2);
                string += String.fromCharCode(((c & 15) << 12) | ((c2 & 63) << 6) | (c3 & 63));
                i += 3;
            }
        }
        return string;
    }
};
/**
 * @method
 * @name ShiftCrossBrowser_Request
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_Request = function() {
    var url = location.href;
    var param = new Object();
    if (url.indexOf("?") != -1) {
        var queryString = url.substring(url.indexOf("?") + 1);
        var paramList = queryString.split("&");
        for (i = 0; i < paramList.length; i++) {
            var tmp = paramList[i];
            tmp = tmp.split("=");
            str = "param." + tmp[0] + "= '" + tmp[1] + "'";
            eval(str);
        }
    }
    this.getParameter = function(str) {
        var result = eval("param." + str);
        if (typeof(result) == "undefined") {
            return null;
        } else {
            return result;
        }
    };
};
ShiftCrossBrowser_request = new ShiftCrossBrowser_Request();
scwin.ShiftCrossBrowser_BrowserDetect = {
    init: function() {
        this.browser = this.searchString(this.dataBrowser) || "An unknown browser";
        this.version = this.searchVersion(navigator.userAgent) || this.searchVersion(navigator.appVersion) || "an unknown version";
        this.OS = this.searchString(this.dataOS) || "an unknown OS";
        this.OSVersion = this.searchString(this.dataOSVersion) || "an unknown OS";
        this.browserVersion = this.searchString(this.dataBrowserVersion) || "an unknown browser version";
    },
    searchString: function(data) {
        for (var i = 0; i < data.length; i++) {
            var dataString = data[i].string;
            var dataProp = data[i].prop;
            this.versionSearchString = data[i].versionSearch || data[i].identity;
            if (dataString) {
                if (dataString.indexOf(data[i].subString) != -1) return data[i].identity;
            } else if (dataProp) return data[i].identity;
        }
    },
    searchVersion: function(dataString) {
        var index = dataString.indexOf(this.versionSearchString);
        if (index == -1) return;
        return parseFloat(dataString.substring(index + this.versionSearchString.length + 1));
    },
    dataBrowser: [{
        string: navigator.vendor,
        subString: "Apple",
        identity: "Safari",
        versionSearch: "Version"
    }, {
        prop: window.opera,
        identity: "Opera",
        versionSearch: "Version"
    }, {
        string: navigator.userAgent,
        subString: "OPR",
        identity: "Opera"
    }, {
        string: navigator.userAgent,
        subString: "Firefox",
        identity: "Firefox"
    }, {
        string: navigator.userAgent,
        subString: "MSIE",
        identity: "Explorer",
        versionSearch: "MSIE"
    }, {
        string: navigator.userAgent,
        subString: "Trident",
        identity: "Explorer",
        versionSearch: "MSIE"
    }, {
        string: navigator.userAgent,
        subString: "Chrome",
        identity: "Chrome"
    }, {
        string: navigator.userAgent,
        subString: "Gecko",
        identity: "Mozilla",
        versionSearch: "rv"
    }, {
        string: navigator.userAgent,
        subString: "Mozilla",
        identity: "Netscape",
        versionSearch: "Mozilla"
    }],
    dataOS: [{
        string: navigator.platform,
        subString: "Win",
        identity: "Windows"
    }, {
        string: navigator.platform,
        subString: "Mac",
        identity: "Mac"
    }, {
        string: navigator.userAgent,
        subString: "iPhone",
        identity: "iPhone/iPod"
    }, {
        string: navigator.platform,
        subString: "Linux",
        identity: "Linux"
    }],
    dataOSVersion: [{
        string: window.navigator.appVersion,
        subString: "Windows NT 6.1",
        identity: "6.1"
    }, {
        string: window.navigator.appVersion,
        subString: "Windows NT 6.0",
        identity: "6.0"
    }],
    dataBrowserVersion: [{
        string: window.navigator.cpuClass,
        subString: "x86",
        identity: "x86"
    }, {
        string: window.navigator.cpuClass,
        subString: "x64",
        identity: "x64"
    }]
};
scwin.ShiftCrossBrowser_BrowserDetect.init();
/**
 * @method
 * @name ShiftCrossBrowser_OSVersion
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_OSVersion = function() {
    var version = window.navigator.appVersion;
    if (version.indexOf("Windows NT") != -1) return version.substr(version.indexOf("Windows NT") + 11, 3);
    return 0;
};
/**
 * @method
 * @name ShiftCrossBrowser_Checkurl
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_Checkurl = function() {
    if (typeof(shift_checkurl_08) != 'undefined') return true;
};
/**
 * @method
 * @name ShiftCrossBrowser_setting
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShiftCrossBrowser_setting = function() {
    if (typeof(shift_checkurl_08) != 'undefined') shift_checkurl_08.sendRequest({
        type: 'SETTING',
        value: 'SHIFT_CROSS_BROWSER',
        file__SHIFT_CHROME_EXTENTION: file__SHIFT_CHROME_EXTENTION,
        ver: '',
        exefile__SHIFT_CHROME_EXE: exefile__SHIFT_CHROME_EXE,
        key: SHIFT_LICENSE_KEY,
        browser: 'browser=' + scwin.ShiftCrossBrowser_BrowserDetect.browser + ',' + scwin.SHIFT_OPENWINDOW_OPTION + ',openwindow=' + scwin.SHIFT_OPENWINDOW,
        icon: scwin.SHIFT_OPENWINDOW_TITLEICON,
        emulation: scwin.SHIFT_BROWSER_EMULATION,
        userDown: scwin.SHIFT_USER_DOWNLOADPAGE
    });
};
/**
 * @method
 * @name CREATE_SHIFTCROSSBROWSER
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CREATE_SHIFTCROSSBROWSER = function() {
    var head = document.getElementsByTagName('head')[0];
    var script = document.createElement('meta');
    script.httpEquiv = "Cache-Control";
    script.content = "no-cache";
    head.appendChild(script);
    script.httpEquiv = "Expires";
    script.content = "0";
    head.appendChild(script);
    script.httpEquiv = "Pragma";
    script.content = "no-cache";
    head.appendChild(script);
    if (scwin.ShiftCrossBrowser_BrowserDetect.browser == "Chrome" && parseInt(window.navigator.appVersion.match(/Chrome\/(\d+)\./)[1], 10) >= 42) {
        if (this.ShiftCrossBrowser_Checkurl()) {
            this.ShiftCrossBrowser_setting();
            return;
        } else {
            if (typeof(scwin.SHIFT_USER_DOWNLOADPAGE) != "undefined" && scwin.SHIFT_USER_DOWNLOADPAGE.trim().length > 0) document.location = scwin.SHIFT_USER_DOWNLOADPAGE;

            else document.location = scwin.SHIFT_CHROME_EXTENTION;
        }
    } else {
        var bIE64Bit = (scwin.ShiftCrossBrowser_BrowserDetect.browser == "Explorer" && scwin.ShiftCrossBrowser_BrowserDetect.browserVersion == "x64") ? "true" : "false";
        if (scwin.ShiftCrossBrowser_BrowserDetect.browser != "Explorer" || bIE64Bit == "true") {
            scwin.ShiftCrossBrowser_pluginVersion();
            var obj = "";
            var b = scwin.ShiftCrossBrowser_BrowserDetect.browser;
            if (scwin.SHIFT_DEFAULT_PLUGINLOAD == "true" && scwin.SHIFT_DEFAULT_PLUGININSTALL == "false") {
                obj += '<embed                                                                                          ';
                if (bIE64Bit == "true") {
                    obj += ' type   ="' + scwin.SHIFT_DEFAULT_MIME + '"                                                           ';
                    obj += ' id     ="shift"                                                                            ';
                    obj += ' ie64bit="true"                                                                             ';
                } else {
                    obj += ' type   ="' + scwin.SHIFT_DEFAULT_MIME + ',version=' + scwin.SHIFT_VERSION + '"                                 ';
                }
                obj += ' width  ="' + scwin.SHIFT_DEFAULT_WIDTH + '"                                                              ';
                obj += ' height ="' + scwin.SHIFT_DEFAULT_HEIGHT + '"                                                             ';
                obj += ' srcurl ="' + scwin.SHIFT_DEFAULT_URL + '?SHIFT_MOZILA_PLUGIN=true"                                       ';
                obj += ' openwindow ="' + scwin.SHIFT_OPENWINDOW + '"                                                             ';
                obj += ' openwindowoption = "browser=' + b + ',' + scwin.SHIFT_OPENWINDOW_OPTION + '"                                 ';
                obj += ' openwindowtitleicon ="' + scwin.SHIFT_OPENWINDOW_TITLEICON + '"                                          ';
                obj += ' key ="' + SHIFT_LICENSE_KEY + '"                                          ';
                obj += '/>                                                                                              ';
            } else {
                obj += "<table width='100%' height='100%' style='color:white;font-size__14px'><tr><td align='center' valign='middle'><img src=" + scwin.SHIFT_BACKGROUND + "></td></tr></table>";
            }
            document.body.innerHTML = obj;
            document.body.style.margin = "0px 0px 0px 0px";
            document.body.style.padding = "0px 0px 0px 0px";
            document.body.style.overflow = "hidden";
            if (scwin.SHIFT_DEFAULT_PLUGINLOAD == "false" || scwin.SHIFT_DEFAULT_PLUGININSTALL == "true") {
                setTimeout(ShiftCrossBrowser_pluginDownload, 1000);
                scwin.SHIFT_DEFAULT_REPLACEFLAG = setInterval(ShiftCrossBrowser_pluginReplace, 1000);
                return;
            }
        }
    }
};
if (window.addEventListener) window.addEventListener("load", CREATE_SHIFTCROSSBROWSER, false);

else if (window.attachEvent) window.attachEvent("onload", CREATE_SHIFTCROSSBROWSER);
